import { build, loadConfigFromFile } from './tabnode-witness/node_modules/vite/dist/node/index.js';
import { resolve } from 'node:path';
const loaded = await loadConfigFromFile({ command: 'build', mode: 'production' }, 'vite.lib.config.js');
if (!loaded) throw new Error('Original Vite config was not loaded.');
const config = loaded.config;
const worker = resolve('src/worker/runtime-worker.ts');
const retained = resolve('../private-runtime-worker/runtime-worker.mjs');
if (process.argv[2] === 'worker') {
  await build({ ...config, configFile: false, plugins: config.worker.plugins(),
    build: { ...config.build, emptyOutDir: false, outDir: resolve('../private-runtime-worker'),
      lib: { ...config.build.lib, entry: { 'runtime-worker': worker } },
      rollupOptions: config.worker.rollupOptions,
    },
  });
} else if (process.argv[2] === 'index') {
  await build({ ...config, configFile: false,
    worker: { ...config.worker, plugins: () => [
      { name: 'retained-original-worker-output', enforce: 'pre', resolveId(source) {
        return source === worker ? retained : null;
      } },
      ...config.worker.plugins(),
    ] },
    build: { ...config.build, emptyOutDir: false,
      lib: { ...config.build.lib, entry: { index: config.build.lib.entry.index } },
    },
  });
} else throw new Error('Select exactly one original worker or index output.');
